const puppeteer = require('puppeteer-core');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = process.argv[2];
const OUT = process.argv[3];
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const server = http.createServer((req, res) => {
  const f = path.join(ROOT, decodeURIComponent(req.url.split('?')[0]));
  if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'Content-Type': f.endsWith('.html') ? 'text/html' : f.endsWith('css2') ? 'text/css' : 'application/octet-stream' });
  fs.createReadStream(f).pipe(res);
}).listen(8767);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const FILES = { A: 'saved_resource.html', B: 'saved_resource(1).html' };

async function click(page, label, log) {
  const h = await page.evaluateHandle((label) => {
    const norm = s => (s || '').trim().replace(/\s+/g, ' ').toLowerCase();
    const L = label.toLowerCase();
    const els = [...document.querySelectorAll('button, a, [role=switch], [role=radio], input, label')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; });
    // prefer elements inside an open dialog if one exists
    const dlg = [...document.querySelectorAll('[role=dialog],[aria-modal=true],dialog[open]')].pop();
    const pool = dlg ? els.filter(e => dlg.contains(e)).concat(els) : els;
    return pool.find(e => norm(e.getAttribute('aria-label')) === L) || pool.find(e => norm(e.innerText) === L) || pool.find(e => norm(e.innerText).startsWith(L)) || pool.find(e => norm(e.getAttribute('aria-label')).startsWith(L)) || pool.find(e => norm(e.innerText).includes(L));
  }, label);
  const el = h.asElement();
  if (!el) { log.push(`[${label}] NOT FOUND`); return false; }
  await el.evaluate(e => e.scrollIntoView({ block: 'center' }));
  await sleep(150);
  await el.click().catch(e => log.push(`[${label}] click err ${e.message}`));
  await sleep(1300);
  return true;
}
async function dialogText(page) {
  return page.evaluate(() => [...document.querySelectorAll('[role=dialog],[aria-modal=true],dialog[open],[role=status],[role=alert]')].map(d => d.innerText.trim().replace(/\s+/g, ' ').slice(0, 400)).filter(Boolean));
}

(async () => {
  const browser = await puppeteer.launch({ executablePath: CHROME, headless: 'new', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--no-sandbox'] });
  for (const k of ['A', 'B']) {
    const dl = path.join(OUT, `dl2_${k}`); fs.mkdirSync(dl, { recursive: true });
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    const cdp = await page.createCDPSession();
    await cdp.send('Browser.setDownloadBehavior', { behavior: 'allow', downloadPath: dl });
    const log = [];
    page.on('pageerror', e => log.push(`[pageerror] ${e.message}`));
    page.on('console', m => { if (m.type() === 'error') log.push(`[console.error] ${m.text()}`); });
    await page.goto(`http://localhost:8767/${encodeURIComponent(FILES[k])}`, { waitUntil: 'networkidle2' });
    await sleep(3000);
    const shot = async name => page.screenshot({ path: path.join(OUT, `${k}_${name}.png`) });

    // Front-on colour + expression states (no drag)
    const colors = k === 'A' ? ['Lilac', 'Matcha', 'Butter', 'Ink', 'Tangerine'] : ['Peach body color', 'Lilac body color', 'Sage body color', 'Cloud body color', 'Butter body color'];
    for (const c of colors) { await click(page, c, log); await page.evaluate(() => scrollTo(0, 0)); await sleep(1200); await shot('c_' + c.split(' ')[0]); }
    const exprs = k === 'A' ? ['Wink', 'Dreamy', 'Gentle'] : ['Dreamy', 'Curious', 'Happy'];
    for (const e of exprs) { await click(page, e, log); await page.evaluate(() => scrollTo(0, 0)); await sleep(1200); await shot('e_' + e); }
    if (k === 'B') { await click(page, 'Glossy', log); await page.evaluate(() => scrollTo(0, 0)); await sleep(1500); await shot('f_Glossy'); await click(page, 'Soft matte', log); }

    // zoom test
    await page.evaluate(() => scrollTo(0, 0)); await sleep(300);
    const box = await (await page.$('canvas')).boundingBox();
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    for (let i = 0; i < 6; i++) { await page.mouse.wheel({ deltaY: -250 }); await sleep(60); }
    await sleep(1000);
    log.push(`zoom: scrollY after wheel=${await page.evaluate(() => scrollY)}`);
    await page.evaluate(() => scrollTo(0, 0)); await sleep(300);
    await shot('zoom_in');
    await click(page, k === 'A' ? 'Reset view' : 'Reset camera view', log);
    await page.evaluate(() => scrollTo(0, 0)); await sleep(1000);
    await shot('after_reset');

    // Export / download flows
    if (k === 'A') {
      await click(page, 'Download model GLB', log); await shot('dlg_download');
      log.push('download dialog: ' + JSON.stringify(await dialogText(page)));
      await click(page, '3D model', log); await sleep(2500);
      log.push('after 3D model click: ' + JSON.stringify(await dialogText(page)));
      await shot('dlg_download_after_glb');
      const btns = await page.evaluate(() => [...document.querySelectorAll('[role=dialog] button, [aria-modal=true] button')].map(b => (b.innerText || b.getAttribute('aria-label') || '').trim().replace(/\s+/g, ' ')));
      log.push('dialog buttons: ' + JSON.stringify(btns));
    } else {
      await click(page, 'Export character', log); await shot('dlg_export');
