    if (!visible) { log.push(`#${c.i} "${c.name}" not visible now (skipped)`); continue; }
    const before = { text: await s.text(), y: await f.evaluate(() => scrollY), url: await f.evaluate(() => location.href), files: fs.readdirSync(dl).length, logs: log.length };
