  if (dlBtn) { await s.click({ text: dlBtn, sel: '[role=dialog] button' }, 2500); log.push(`after "${dlBtn}": toast="${await toast()}" dialogs=${JSON.stringify(await dlg())} files=${JSON.stringify(fs.readdirSync(dl))}`); }
  // PNG option
  const png = dbtns.find(b => /PNG|image/i.test(b));
  if (png) { await s.click({ text: png, sel: '[role=dialog] button,[role=dialog] [role=radio],[role=dialog] label' }, 600); const b3 = await f.evaluate(() => [...document.querySelectorAll('[role=dialog] button')].map(b => b.innerText.trim().replace(/\s+/g, ' ')).find(t => /^download/i.test(t))); if (b3) { await s.click({ text: b3, sel: '[role=dialog] button' }, 2500); log.push(`after "${b3}": toast="${await toast()}" files=${JSON.stringify(fs.readdirSync(dl))}`); } }
  await page.keyboard.press('Escape'); await sleep(600);
  // collection
  await s.click({ label: 'Save Forma X1 to collection' }, 1000); log.push('after save: ' + await f.evaluate(() => document.querySelector('header')?.innerText.replace(/\s+/g, ' ')));
  await s.click({ text: 'My collection' }, 1000); log.push('collection: ' + JSON.stringify(await dlg())); await shot('collection'); await page.keyboard.press('Escape'); await sleep(600);
  // nav + footer links
  for (const q of [{ text: 'The details' }, { text: 'License' }, 'ESC', { text: 'Make it part of your next project' }, 'ESC', { text: 'CC0 1.0' }, 'ESC', { text: "Let's make it big" }, 'ESC', { text: 'About the studio' }, 'ESC', { text: 'Quick start' }, 'ESC', { label: 'Back to Forma Studio' }, { text: 'Free for personal' }, 'ESC']) {
    if (q === 'ESC') { await page.keyboard.press('Escape'); await sleep(500); continue; }
    const y0 = await f.evaluate(() => scrollY); const t0 = await s.text();
    await s.click(q, 1000);
    const y1 = await f.evaluate(() => scrollY); const d = await dlg(); const t1 = await s.text();
    const added = t1.split('\n').filter(l => l.trim() && !t0.includes(l)).slice(0, 4).join(' | ').slice(0, 140);
    log.push(`${JSON.stringify(q)}: scroll ${y0}->${y1} dialogs=${JSON.stringify(d.map(x => x.slice(0, 70)))} ${added ? '+[' + added + ']' : ''}`);
  }
  console.log(log.filter(l => !/allow-scripts|404|WebGLShadow|THREE/.test(l)).join('\n'));
  await s.close();
})();

