// Press the shot key when the meter reaches the sweet zone (using aria-valuenow), log what the page saw.
const { open, sleep } = require('./frame');
const [ROOT, FILE, METER, KEY, TARGET, BALLS] = process.argv.slice(2);
(async () => {
  const s = await open(ROOT, FILE, { width: 1440, height: 900, sandbox: false }); await sleep(2000);
  const { frame: f, page } = s;
  await s.click({ text: 'LET’S PLAY' }, 300);
  await f.evaluate((METER) => { window.__k = []; window.addEventListener('keydown', e => { const m = document.querySelector(METER); window.__k.push(`${e.code} at meter=${m ? m.getAttribute('aria-valuenow') : '?'}`); }, true); }, METER);
  const res = [];
  for (let b = 0; b < +BALLS; b++) {
    // wait until meter value crosses TARGET (in-page wait, then press from node)
    const ok = await f.evaluate((METER, T) => new Promise(r => { const t0 = performance.now(); const loop = () => { const m = document.querySelector(METER); const v = m ? +m.getAttribute('aria-valuenow') : -1; if (v >= T && v < T + 6) return r(v); if (performance.now() - t0 > 15000) return r('timeout'); requestAnimationFrame(loop); }; loop(); }), METER, +TARGET);
    await page.keyboard.press(KEY);
    await sleep(2600);
    const live = await f.evaluate(() => [...document.querySelectorAll('[aria-live],[role=status]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 100));
    res.push(`ball ${b + 1}: waited->${ok} | ${live}`);
    if (ok === 'timeout') break;
  }
  console.log(res.join('\n')); console.log('keys seen: ' + JSON.stringify(await f.evaluate(() => window.__k)));
  await s.close();
})();

