input.content:
// Full-match driver.
// usage: node cricket_match.js <root> <file> <outDir> <A|B> <plan>
//  plans: A_full  -> bat (early lofts to lose wickets) then bowl innings 2 to the result
//         B_chase -> bat with perfect timing to win the chase
//         B_bowl  -> bowling mode, release near 72%, play up to 30 balls
//         odi     -> select ODI, start, report header
const { open, sleep } = require('./frame'); const path = require('path'); const fs = require('fs');
const [ROOT, FILE, OUT, TAG, PLAN, WIDTH = '1440'] = process.argv.slice(2);
(async () => {
  const W = +WIDTH; const s = await open(ROOT, FILE, { width: W, height: W >= 1440 ? 900 : 800, sandbox: W < 1440 }); await sleep(2000);
  const { frame: f, page, log } = s; const rows = [];
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${PLAN}_${String(++n).padStart(2, '0')}_${name}.png`));
  const text = () => s.text();
  const live = () => f.evaluate(() => [...document.querySelectorAll('[role=status],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 160));
  // meter value 0..100
  const meterVal = TAG === 'A'
    ? () => f.evaluate(() => { const m = document.querySelector('[role=meter]'); return m ? +m.getAttribute('aria-valuenow') : -1; })
    : () => f.evaluate(() => { const n = document.querySelector('.meter-needle'); return n ? parseFloat(n.style.left) || -1 : -1; });
  const waitMeter = (lo, hi, timeout = 12000) => f.evaluate((TAG, lo, hi, timeout) => new Promise(r => {
    const t0 = performance.now(); const get = () => { if (TAG === 'A') { const m = document.querySelector('[role=meter]'); return m ? +m.getAttribute('aria-valuenow') : -1; } const n = document.querySelector('.meter-needle'); return n ? parseFloat(n.style.left) || -1 : -1; };
    const loop = () => { const v = get(); if (v >= lo && v <= hi) return r(v); if (performance.now() - t0 > timeout) return r('timeout'); requestAnimationFrame(loop); }; loop();
  }), TAG, lo, hi, timeout);
  const scoreLine = () => f.evaluate(() => { const sb = document.querySelector('.scoreboard'); return sb ? sb.innerText.replace(/\s+/g, ' ').slice(0, 120) : ''; });

  if (PLAN === 'odi') {
    await s.click({ text: 'ODI' }, 600); await s.click({ text: 'LET’S PLAY' }, 3500);
    rows.push('ODI scoreboard: ' + await scoreLine()); await shot('odi');
  }

  if (PLAN === 'A_full') {
    await s.click({ text: 'LET’S PLAY' }, 300);
    let balls = 0;
    // innings 1: early lofts
    while (balls < 90) {
      const v = await waitMeter(36, 44, 9000);
      if (v === 'timeout') { const t = await text(); if (/break|innings break|2nd innings|target/i.test(t) && !/1ST INNINGS/.test(await scoreLine())) break; rows.push('timeout waiting meter; scoreboard=' + await scoreLine()); const tt = t.split('\n').filter(l => /BREAK|INNINGS|TARGET|NEED|CHASE|DEFEND|SET/i.test(l)).slice(0, 8).join(' | '); rows.push('  page: ' + tt); break; }
      await page.keyboard.press('KeyD'); balls++;
      await sleep(1700);
      if (balls % 5 === 0) rows.push(`inn1 ball ${balls}: ${await scoreLine()} | ${await live()}`);
    }
    await sleep(1500); await shot('innings_break');
    rows.push('BREAK PAGE: ' + (await text()).split('\n').filter(l => l.trim()).filter(l => /BREAK|INNINGS|TARGET|NEED|DEFEND|runs|win|BOWL/i.test(l)).slice(0, 12).join(' | '));
    // continue to innings 2
    const btn = await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.getBoundingClientRect().width > 0 && /2nd innings|second innings|let.s bowl|start bowling|continue|take the field|next innings|innings/i.test(b.innerText)));
    if (btn.asElement()) { rows.push('clicking: ' + await btn.asElement().evaluate(b => b.innerText.trim().replace(/\s+/g, ' '))); const bb = await btn.asElement().boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); } else { rows.push('no innings button; pressing Enter'); await page.keyboard.press('Enter'); }
    await sleep(1500); rows.push('INN2 start: ' + await scoreLine()); await shot('innings2_start');
    // innings 2: bowl, release at sweet spot, rotate delivery types
    let b2 = 0; const types = ['KeyA', 'KeyS', 'KeyD'];
    while (b2 < 130) {
      const t = await scoreLine(); const st = await f.evaluate(() => document.body.innerText);
      if (/win by|tie!|That’s how you do it|The next one is yours/i.test(st)) break;
      await page.keyboard.press(types[b2 % 3]); await sleep(100);
      const v = await waitMeter(78, 82, 9000);
      if (v === 'timeout') { rows.push('inn2 meter timeout at ' + t); break; }
      await page.keyboard.press('Space'); b2++;
      await sleep(2600);
      if (b2 % 4 === 0) rows.push(`inn2 ball ${b2}: ${await scoreLine()} | ${await live()}`);
    }
    await sleep(2000); await shot('result');
    rows.push('RESULT PAGE: ' + (await text()).split('\n').filter(l => l.trim()).filter(l => /win by|tie|how you do it|next one is yours|WHAT A MATCH|runs|wickets/i.test(l)).slice(0, 10).join(' | '));
    rows.push('result dialog: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)))));
    await page.keyboard.press('Escape'); await sleep(500);
    await s.click({ label: 'View your player stats' }, 900); await shot('stats');
    rows.push('STATS: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)))));
  }

  if (PLAN === 'B_chase') {
    await s.click({ text: 'LET’S PLAY' }, 300);
    let balls = 0;
    while (balls < 60) {
      const st = await text(); if (/THAT’S A WIN|GO AGAIN\?/.test(st) && /ONE MORE INNINGS/.test(st)) break;
      const v = await waitMeter(79.5, 81.5, 12000);
      if (v === 'timeout') { rows.push('meter timeout; ' + await scoreLine()); break; }
      await page.keyboard.press('Space'); balls++;
      await sleep(400); if (balls === 2) await shot('mid_shot');
      await sleep(2000);
      if (balls % 4 === 0) rows.push(`ball ${balls}: ${await scoreLine()} | ${await live()}`);
    }
    await sleep(2500); await shot('result');
    rows.push('RESULT: ' + (await text()).split('\n').filter(l => l.trim()).filter(l => /WIN|GO AGAIN|chase|overs\.|INNINGS/i.test(l)).slice(0, 8).join(' | '));
    await s.click({ text: 'View scorecard' }, 1000); await shot('scorecard');
    rows.push('SCORECARD: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)))));
    await page.keyboard.press('Escape'); await sleep(500);
    await s.click({ label: 'View your player stats' }, 900); await shot('stats');
    rows.push('STATS: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)))));
  }

  if (PLAN === 'B_bowl' || PLAN === 'A_bowl') {
    await s.click({ text: 'Bowling' }, 500); await s.click({ text: 'LET’S PLAY' }, 1500);
