      const t = await scoreLine(); const st = await f.evaluate(() => document.body.innerText);
      if (/win by|tie!|That’s how you do it|The next one is yours/i.test(st)) break;
      await page.keyboard.press(types[b2 % 3]); await sleep(100);
      const v = await waitMeter(78, 82, 9000);
      if (v === 'timeout') { rows.push('inn2 meter timeout at ' + t); break; }
      await page.keyboard.press('Space'); b2++;
      await sleep(2600);
