// Test the scroll-tour edit inside the Editing wrapper (task frame W x 800, sandboxed), real mouse only.
// usage: node tour_test.js <filesDir> <wrapper> <afterFile> <A|B> <width> <outDir>
const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, WRAP, AFTER, TAG, WIDTH, OUT] = process.argv.slice(2);
const W = +WIDTH;
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, WRAP, { width: W, height: 800, sandbox: true });
  const { page, log } = s;
  let fr = null;
  for (let i = 0; i < 40 && !fr; i++) { fr = page.frames().find(f => decodeURIComponent(f.url()).includes(AFTER)); if (!fr) await sleep(500); }
  if (!fr) { console.log('after frame not found', page.frames().map(f => f.url())); return s.close(); }
  await sleep(6000);
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${W}_${String(++n).padStart(2, '0')}_${name}.png`));
  const info = await fr.evaluate(() => ({ vw: innerWidth, vh: innerHeight, docH: document.documentElement.scrollHeight, title: document.title }));
  log.push(`after-frame viewport ${info.vw}x${info.vh}, doc height ${info.docH}`);
  await shot('initial');
  const findTourBtn = () => fr.evaluateHandle((TAG) => TAG === 'A'
    ? document.querySelector('aside[aria-label="Full-page animation tour"] button')
    : document.querySelector('button[data-tour-control]'), TAG);
  let btn = (await findTourBtn()).asElement();
