const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(2500);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const text = () => f.evaluate(() => document.body.innerText.replace(/\s+/g, ' '));
  const score = () => f.evaluate(() => { const t = document.body.innerText; const m = t.match(/(YOUR SCORE|SCORE)\s*\n(?:PTS\s*\n)?\s*(\d+)/i); const b = t.match(/(PERSONAL BEST|BEST)\s*\n\s*(\d+)/i); return `score=${m ? m[2] : '?'} best=${b ? b[2] : '?'}`; });
  const state = () => f.evaluate((TAG) => {
    const svg = [...document.querySelectorAll('svg')].sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width)[0];
    const sn = svg.querySelector('[class*=snake]'); const food = svg.querySelector('[class*=food]');
    if (!sn) return null;
    const kids = [...sn.children];
    const head = TAG === 'A' ? kids[kids.length - 1] : kids[kids.length - 3];
    const hr = head.getBoundingClientRect(); const fr = food ? food.getBoundingClientRect() : null;
    const sr = svg.getBoundingClientRect(); const vb = svg.viewBox.baseVal;
    const cell = (TAG === 'A' ? 25 : 24) * sr.width / vb.width;
    return { hx: hr.x + hr.width / 2, hy: hr.y + hr.height / 2, fx: fr ? fr.x + fr.width / 2 : null, fy: fr ? fr.y + fr.height / 2 : null, cell, len: TAG === 'A' ? kids.length : kids.filter(k => k.tagName === 'rect' && k.getBoundingClientRect().width > 10).length, cls: sn.getAttribute('class') };
  }, TAG);
  // start with real click
  await s.click({ text: TAG === 'A' ? "Let's play" : 'START GAME' }, 400);
  log.push('after start: ' + await score() + ' | ' + JSON.stringify(await state()));
  let dir = 'right'; const opp = { up: 'down', down: 'up', left: 'right', right: 'left' }; const key = { up: 'ArrowUp', down: 'ArrowDown', left: 'ArrowLeft', right: 'ArrowRight' };
  const t0 = Date.now(); let lastScore = ''; let eats = 0;
  while (Date.now() - t0 < 45000) {
    const st = await state(); if (!st || st.fx === null) { await sleep(40); continue; }
    const dx = st.fx - st.hx, dy = st.fy - st.hy, h = st.cell / 2;
    let want = Math.abs(dx) > h ? (dx > 0 ? 'right' : 'left') : Math.abs(dy) > h ? (dy > 0 ? 'down' : 'up') : dir;
    if (want === opp[dir]) want = Math.abs(dy) > h ? (dy > 0 ? 'down' : 'up') : (dir === 'left' || dir === 'right' ? 'up' : 'left');
    if (want !== dir) { await page.keyboard.press(key[want]); dir = want; }
    const sc = await score(); if (sc !== lastScore) { if (lastScore) { eats++; log.push(`  ${Math.round((Date.now() - t0) / 1000)}s ${sc} len=${st.len}`); } lastScore = sc; if (eats === 2) await shot('playing'); }
    if (eats >= 5) break;
    if (/Game over|GAME OVER/.test(await text())) { log.push('died early'); break; }
    await sleep(25);
  }
  // pause test
  await page.keyboard.press('Space'); await sleep(800); const p1 = await state(); await sleep(1000); const p2 = await state();
  log.push(`pause via Space: head moved? ${p1 && p2 ? Math.abs(p1.hx - p2.hx) + Math.abs(p1.hy - p2.hy) > 1 : '?'} | ${(await text()).match(/(On a little break|Take a breather|PAUSED|Paused)[^.]*\.?/i)?.[0]}`);
  await shot('paused');
  // pace button during pause
  const paceBefore = await f.evaluate(() => [...document.querySelectorAll('button')].filter(b => /^(chill|classic|fast)$/i.test(b.innerText.trim())).map(b => `${b.innerText.trim()}:${b.getAttribute('aria-pressed') || b.getAttribute('aria-checked') || ''}:${b.disabled ? 'disabled' : ''}`).join(' '));
  log.push('pace buttons during pause: ' + paceBefore);
  await page.keyboard.press('Space'); await sleep(300);
  // die into wall: keep going current direction
  const t1 = Date.now(); while (Date.now() - t1 < 15000) { if (/Game over|GAME OVER/.test(await text())) break; await sleep(100); }
  await sleep(800); log.push('game over: ' + (await text()).match(/(Game over|GAME OVER).{0,160}/)?.[0]); log.push('after death: ' + await score()); await shot('gameover');
  // on-screen arrows / swipe
  await s.click({ text: TAG === 'A' ? 'Play again' : 'PLAY AGAIN' }, 500);
  const a0 = await state();
  if (TAG === 'A') { await s.click({ label: 'Move down' }, 600); }
  else { const svgBox = await (await f.$('[role=group][aria-label^="Game board"]')).boundingBox(); await page.mouse.move(svgBox.x + svgBox.width / 2, svgBox.y + svgBox.height / 2); await page.mouse.down(); await page.mouse.move(svgBox.x + svgBox.width / 2, svgBox.y + svgBox.height / 2 + 120, { steps: 6 }); await page.mouse.up(); await sleep(600); }
  const a1 = await state();
  log.push(`${TAG === 'A' ? 'on-screen Move down button' : 'mouse swipe down on board'}: head y ${Math.round(a0.hy)} -> ${Math.round(a1.hy)} (x ${Math.round(a0.hx)} -> ${Math.round(a1.hx)})`);
  // B: are the arrow hints clickable?
  if (TAG === 'B') { const arr = await f.evaluate(() => [...document.querySelectorAll('kbd,span,div,button')].filter(e => e.innerText && /^[↑↓←→]$/.test(e.innerText.trim())).map(e => e.tagName + (e.closest('button') ? '(in button)' : '')).join(',')); log.push('B arrow hint elements: ' + (arr || 'svg icons only')); }
  // reload to check best persists
  await f.evaluate(() => location.reload()); await sleep(3000);
  const f2 = page.frames().find(x => x !== page.mainFrame());
  log.push('after reload: ' + await f2.evaluate(() => { const t = document.body.innerText; const b = t.match(/(PERSONAL BEST|BEST)\s*\n\s*(\d+)/i); return 'best=' + (b ? b[2] : '?'); }));
  fs.writeFileSync(path.join(OUT, `${TAG}_bot.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

