const fs = require('fs'); const path = require('path'); const crypto = require('crypto');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3500);
  const { frame: f, page, log } = s;
  const cv = await f.$('canvas'); await cv.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(500);
  const canvasShot = async (name) => { const bb = await cv.boundingBox(); const clip = { x: Math.max(0, bb.x), y: Math.max(0, bb.y), width: Math.min(bb.width, 1000 - Math.max(0, bb.x)), height: Math.min(bb.height, 800 - Math.max(0, bb.y)) }; const buf = await page.screenshot({ clip, path: path.join(OUT, `${TAG}_${name}.png`) }); return crypto.createHash('md5').update(buf).digest('hex').slice(0, 8); };
  const txt = () => s.text();
  const diffTxt = async (before) => (await txt()).split('\n').filter(l => l.trim() && !before.includes(l)).slice(0, 6).join(' | ').slice(0, 220);
  const step = async (q, name, wait = 1500) => { const b = await txt(); const el = await s.click(q, wait); const h = await canvasShot(name); log.push(`${JSON.stringify(q)} found=${!!el} canvas=${h} +[${await diffTxt(b)}]`); };
  log.push('initial canvas ' + await canvasShot('00_initial'));
  if (TAG === 'A') {
    await step({ text: 'Exploded' }, '01_exploded', 2500);
    await step({ text: 'Cutaway' }, '02_cutaway', 2500);
    await step({ label: 'Hide labels' }, '03_labels_off');
    const lb = await f.evaluate(() => [...document.querySelectorAll('button')].map(b => b.getAttribute('aria-label') || b.innerText.trim()).filter(t => /label/i.test(t)));
    log.push('label buttons now: ' + JSON.stringify(lb));
    await step({ label: lb[0] }, '04_labels_on');
    log.push('labels visible: ' + await f.evaluate(() => [...document.querySelectorAll('*')].filter(e => /^(INTAKE VALVE|PISTON|CRANKSHAFT)$/.test((e.innerText || '').trim()) && e.getBoundingClientRect().width > 0 && e.children.length === 0).length));
    await step({ text: 'The cycle' }, '05_cycle');
    for (const st of ['02 Compression', '03 Power', '04 Exhaust']) await step({ text: st }, '06_' + st.split(' ')[1], 1800);
    await step({ label: 'Play animation' }, '07_play', 3000);
    const a1 = await f.evaluate(() => (document.body.innerText.match(/(\d{3})° \/ 720°/) || [])[1]); await sleep(2000); const a2 = await f.evaluate(() => (document.body.innerText.match(/(\d{3})° \/ 720°/) || [])[1]);
    log.push(`playing: angle ${a1} -> ${a2}, stroke heading now: ${await f.evaluate(() => document.querySelector('[role=tabpanel] h2, h2')?.innerText)}`);
    await canvasShot('08_playing');
    await step({ label: 'Expand viewer' }, '09_expanded'); await page.keyboard.press('Escape'); await sleep(600);
  } else {
    await step({ text: 'Exploded' }, '01_exploded', 2500);
    await step({ text: 'Assembled' }, '02_assembled', 2500);
    const sel = await f.$('select'); for (const v of await sel.evaluate(e => [...e.options].map(o => o.value))) { await sel.select(v); await sleep(1500); log.push(`camera ${v}: ${await canvasShot('03_cam_' + v)}`); }
    await sel.select((await sel.evaluate(e => e.options[0].value))); await sleep(1000);
    await step({ label: 'Hide Main housing' }, '04_hide_housing');
    await step({ label: 'Hide Housing cover' }, '05_hide_cover');
    await step({ label: 'Play simulation' }, '06_play', 500);
    const p = await f.evaluate(() => [...document.querySelectorAll('button')].filter(b => /simulation|play/i.test(b.getAttribute('aria-label') || '')).map(b => b.getAttribute('aria-label')));
    log.push('play buttons: ' + JSON.stringify(p));
    if (!/Pause/i.test(p.join())) await step({ label: p.find(x => /play/i.test(x)) }, '06b_play', 500);
    const h1 = await canvasShot('07_sim1'); await sleep(1500); const h2 = await canvasShot('07_sim2');
    log.push(`simulation moving: ${h1 !== h2} timer=${await f.evaluate(() => (document.body.innerText.match(/\d\d:\d\d/g) || []).join(','))}`);
    // material
    const mat = await f.$('select[aria-label*="aterial" i]') || (await f.$$('select'))[1];
    if (mat) { const opts = await mat.evaluate(e => [...e.options].map(o => o.value)); await mat.select(opts[opts.length - 1]); await sleep(1200); log.push(`material -> ${opts[opts.length - 1]}: ${await canvasShot('08_material')}`); }
    // input speed
    const inp = await f.$('input[type=number]');
    if (inp) { const before = await f.evaluate(() => document.body.innerText.match(/Output speed\s*\n?\s*([\d.]+)/)?.[1] + ' / torque ' + document.body.innerText.match(/Output torque\s*\n?\s*([\d.]+)/)?.[1]); await inp.click({ clickCount: 3 }); await page.keyboard.type('1800'); await page.keyboard.press('Tab'); await sleep(800); const after = await f.evaluate(() => document.body.innerText.match(/Output speed\s*\n?\s*([\d.]+)/)?.[1] + ' / torque ' + document.body.innerText.match(/Output torque\s*\n?\s*([\d.]+)/)?.[1]); log.push(`input speed 1200->1800: output ${before} -> ${after}`); }
    for (const q of [{ label: 'Toggle dimensions' }, { label: 'Toggle floor grid' }, { label: 'Zoom in' }, { label: 'Reset camera' }]) await step(q, '09_' + (q.label.replace(/\W+/g, '_')));
