  const em = await f.evaluate(() => { const svgs = [...document.querySelectorAll('svg')].filter(e => { const r = e.getBoundingClientRect(); return r.top > 60 && r.top < 500 && r.width > 40 && r.width < 200 && r.height > 40; }); svgs.sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width); if (!svgs[0]) return null; const r = svgs[0].getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; });
  if (em) await page.screenshot({ path: path.join(OUT, `${TAG}_hero_emblem_zoom.png`), clip: { x: fb.x + em.x - 8, y: fb.y + em.y - 8, width: em.w + 16, height: em.h + 16 } });
  console.log(TAG, JSON.stringify(box), JSON.stringify(em));
  await s.close();
})();
EOF
