const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true });
  const { page, log } = s;
  const reqs = {};
  page.on('request', r => { const u = r.url(); if (!/\.(html|css|js|svg|png|woff2?)$|css2|fonts|env\.json/.test(u)) { const k = r.method() + ' ' + u.replace(/^https?:\/\/[^/]+/, ''); reqs[k] = (reqs[k] || 0) + 1; } });
  await sleep(3000);
  const f = s.frame;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text();
  const diff = async (before) => (await T()).split('\n').filter(l => l.trim() && !before.includes(l)).slice(0, 8).join(' | ').slice(0, 300);
  const toasts = () => f.evaluate(() => [...document.querySelectorAll('[role=status],[role=alert],[aria-live],.toast,[class*=toast]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' || ').slice(0, 300));
  const glass = await f.evaluate(() => { let c = 0; for (const e of document.querySelectorAll('*')) { const st = getComputedStyle(e); if (st.backdropFilter && st.backdropFilter !== 'none') c++; } return c; });
  log.push(`elements with backdrop blur (glass): ${glass}`);
  log.push(`theme at load: html.class="${await f.evaluate(() => document.documentElement.className)}" bg=${await f.evaluate(() => getComputedStyle(document.body).backgroundColor)}`);
  await shot('load');
  // backend status text
  log.push('mode text: ' + (await T()).split('\n').filter(l => /demo|preview|flask|backend|offline|connect/i.test(l)).slice(0, 6).join(' | '));
  // campaign selector
  let b = await T();
  const sel = await f.$('select[aria-label*="ampaign" i]');
  if (sel) { const opts = await sel.evaluate(e => [...e.options].map(o => o.value + ':' + o.text)); log.push('campaign <select> options ' + JSON.stringify(opts)); await sel.select(opts[1].split(':')[0]); await sleep(1500); }
  else { await s.click({ label: TAG === 'B' ? 'Select campaign, October Outreach' : 'Campaign' }, 700); const opt = (await f.evaluateHandle(() => [...document.querySelectorAll('[role=menuitem],[role=option],[role=menuitemradio],button')].find(e => /^(Product Launch|The weekly edit)/i.test(e.innerText.trim()) && e.getBoundingClientRect().width > 0))).asElement(); if (opt) { const bb = await opt.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1500); } else log.push('no campaign option found'); }
  log.push('campaign switch -> ' + await diff(b) + ' | toast: ' + await toasts()); await shot('campaign_switch');
  // start / stop
  b = await T();
  const ss = await f.evaluate(() => [...document.querySelectorAll('header button, button')].map(x => x.innerText.trim()).find(t => /^(Start sending|Stop sending|Resume|Pause)/i.test(t)));
  await s.click({ text: ss }, 2500); log.push(`clicked "${ss}" -> ${await diff(b)} | toast: ${await toasts()}`); await shot('startstop');
  const p1 = await f.evaluate(() => (document.body.innerText.match(/([\d.]+)\s*%\s*\n?\s*completed/) || [])[1]); await sleep(4000); const p2 = await f.evaluate(() => (document.body.innerText.match(/([\d.]+)\s*%\s*\n?\s*completed/) || [])[1]);
  log.push(`progress over 4s: ${p1} -> ${p2}; status: ${await f.evaluate(() => (document.body.innerText.match(/\b(RUNNING|PAUSED|Running|Paused)\b/) || [])[0])}`);
  // theme toggle
  const themeLbl = await f.evaluate(() => [...document.querySelectorAll('button,[role=switch]')].map(x => x.getAttribute('aria-label') || '').find(t => /dark|light|theme/i.test(t)));
  await s.click({ label: themeLbl }, 1200);
  log.push(`theme toggle "${themeLbl}" -> html.class="${await f.evaluate(() => document.documentElement.className)}" bg=${await f.evaluate(() => getComputedStyle(document.body).backgroundColor)} main=${await f.evaluate(() => getComputedStyle(document.querySelector('main') || document.body).backgroundColor)}`);
  await shot('theme_toggled');
  const themeLbl2 = await f.evaluate(() => [...document.querySelectorAll('button,[role=switch]')].map(x => x.getAttribute('aria-label') || '').find(t => /dark|light|theme/i.test(t)));
  await s.click({ label: themeLbl2 }, 1000);
  // builder: delay input, subjects add/remove, template, variable, preview
  await f.evaluate(() => { const h = [...document.querySelectorAll('h2,h3')].find(x => /Campaign builder/i.test(x.innerText)); h && h.scrollIntoView({ block: 'start' }); }); await sleep(600);
  const subjCount = () => f.evaluate(() => [...document.querySelectorAll('input')].filter(i => /subject/i.test((i.getAttribute('aria-label') || '') + (i.placeholder || '') + (i.name || ''))).length);
  const s0 = await subjCount(); await s.click({ text: 'Add subject' }, 700); const s1 = await subjCount();
  log.push(`subjects: ${s0} -> ${s1} after Add subject`);
  const subjInputs = await f.$$('input'); let lastSubj = null; for (const i of subjInputs) { if (await i.evaluate(e => /subject/i.test((e.getAttribute('aria-label') || '') + (e.placeholder || '') + (e.name || '')))) lastSubj = i; }
  if (lastSubj) { await lastSubj.click({ clickCount: 3 }); await page.keyboard.type('Big news for you'); await sleep(600); }
  const rm = await f.evaluate(() => [...document.querySelectorAll('button')].filter(x => /remove subject|delete subject/i.test(x.getAttribute('aria-label') || '')).length); log.push('remove-subject buttons: ' + rm);
  // first subject edit -> preview?
  const firstSubj = (await f.evaluateHandle(() => [...document.querySelectorAll('input')].find(e => /subject/i.test((e.getAttribute('aria-label') || '') + (e.placeholder || '') + (e.name || ''))))).asElement();
  if (firstSubj) { await firstSubj.click({ clickCount: 3 }); await page.keyboard.type('Zebra test subject {{first_name}}'); await sleep(1000); log.push('preview shows typed subject: ' + await f.evaluate(() => document.body.innerText.includes('Zebra test subject'))); }
  // message textarea edit
  const ta = await f.$('textarea'); if (ta) { await ta.click(); await page.keyboard.press('End'); await page.keyboard.type(' PINEAPPLE'); await sleep(1000); log.push('preview shows typed message: ' + await f.evaluate(() => (document.body.innerText.match(/PINEAPPLE/g) || []).length)); }
  // delay input
  const delay = (await f.evaluateHandle(() => [...document.querySelectorAll('input[type=number],input')].find(e => /delay/i.test((e.getAttribute('aria-label') || '') + (e.id || '') + (e.name || '') + (e.closest('label,div')?.innerText || '').slice(0, 40))))).asElement();
  if (delay) { await delay.click({ clickCount: 3 }); await page.keyboard.type('5'); await page.keyboard.press('Tab'); await sleep(800); log.push('delay text now: ' + (await T()).split('\n').filter(l => /delay|between emails/i.test(l)).slice(0, 3).join(' | ')); }
  // template selector / add template
  b = await T();
  const tsel = (await f.evaluateHandle(() => [...document.querySelectorAll('select')].find(e => [...e.options].some(o => /template|newsletter|follow-up|introduction/i.test(o.text))))).asElement();
  if (tsel) { const o = await tsel.evaluate(e => [...e.options].map(x => x.value + ':' + x.text)); await tsel.select(o[o.length - 1].split(':')[0]); await sleep(900); log.push('template select -> ' + o[o.length - 1] + ' | ' + await diff(b)); }
  else { await s.click({ text: 'Add template' }, 800); log.push('Add template -> ' + await diff(b)); }
  await shot('builder');
  // CSV upload with real file
  const csvPath = path.join(OUT, 'test.csv'); fs.writeFileSync(csvPath, 'email,first_name,company\nzoe@example.com,Zoe,Acme\nmax@example.com,Max,Globex\nbad-email,Bad,X\n');
  const fileInput = await f.$('input[type=file]');
  if (fileInput) { b = await T(); await fileInput.uploadFile(csvPath); await sleep(1500); log.push('CSV upload -> ' + await diff(b) + ' | toast: ' + await toasts()); await shot('csv'); }
